//! The standalone functions in `standalone/generated.rs` were generated by
//! `to_rust_fn` from the fits below. This test checks that they compile and agree with
//! the fitted models, and that the generator still produces exactly that code: after
//! changing the generator, run `BLESS=1 cargo test --test standalone` to rewrite it.
//!
//! The data comes from rational functions only, so the fitted coefficients are the
//! same on every platform with IEEE arithmetic.

use bezier_approx::{Fitter, Model};

include!("standalone/generated.rs");

const GENERATED: &str = "tests/standalone/generated.rs";

/// A generated function, called with a slice.
type Generated = fn(&[f64]) -> f64;

/// The fitted models, their names, and the generated functions.
fn models() -> Vec<(Fitter, &'static str, Generated)> {
    let grid = |steps: usize, lo: f64, hi: f64| {
        (0..=steps).map(move |i| lo + (hi - lo) * i as f64 / steps as f64)
    };
    let mut fit_surface = Fitter::with_model(Model::bezier(2), &[0.0, -1.0], &[1.0, 1.0]);
    for x in grid(8, 0.0, 1.0) {
        for y in grid(8, -1.0, 1.0) {
            fit_surface
                .add_sample([x, y], x * x - x * y + 1.0 / (2.0 + y))
                .unwrap();
        }
    }
    let mut fit_curve = Fitter::spline(3, 4, &[0.0], &[2.0]);
    for x in grid(40, 0.0, 2.0) {
        fit_curve.add_sample([x], x / (1.0 + x * x)).unwrap();
    }
    let mut fit_ramp = Fitter::unit_spline(2, 1, 2);
    for x in grid(10, 0.0, 1.0) {
        for y in grid(10, 0.0, 1.0) {
            fit_ramp
                .add_sample([x, y], (x - 0.4).abs() + x * y)
                .unwrap();
        }
    }
    for fit in [&mut fit_surface, &mut fit_curve, &mut fit_ramp] {
        fit.solve().unwrap();
    }
    vec![
        (fit_surface, "surface", |x| surface([x[0], x[1]])),
        (fit_curve, "curve", |x| curve([x[0]])),
        (fit_ramp, "ramp", |x| ramp([x[0], x[1]])),
    ]
}

#[test]
fn generated_functions_agree_with_the_models() {
    for (fit, name, f) in models() {
        let (lo, hi) = (fit.lo(), fit.hi());
        let last_j = if fit.dims() == 1 { 0 } else { 50 };
        for i in 0..=50 {
            for j in 0..=last_j {
                // 25 % beyond the box on each side, to cover the clamping.
                let x: Vec<f64> = [i, j][..fit.dims()]
                    .iter()
                    .enumerate()
                    .map(|(d, &k)| lo[d] + (hi[d] - lo[d]) * (k as f64 / 33.3 - 0.25))
                    .collect();
                let (got, want) = (f(&x), fit.predict(&x).unwrap());
                assert!(
                    (got - want).abs() < 1e-14,
                    "{name} at {x:?}: {got} vs {want}"
                );
            }
        }
    }
}

#[test]
fn generated_code_is_current() {
    let code: String = models()
        .iter()
        .map(|(fit, name, _)| fit.to_rust_fn(name).unwrap())
        .collect::<Vec<_>>()
        .join("\n");
    if std::env::var_os("BLESS").is_some() {
        std::fs::write(GENERATED, &code).unwrap();
    }
    assert!(
        code == include_str!("standalone/generated.rs"),
        "{GENERATED} is out of date; rerun with BLESS=1 to rewrite it. The generator now \
         produces:\n{code}"
    );
}
